import {field,text,area,number as num,select as sel,e,result,error,download} from '../ui.mjs';
import {recordForm} from './record-form.mjs';
import {table,exportCSV,localChoice,today,need} from './shared.mjs';
import {dateUTC} from '../core.mjs';
import {pageSVG,pagesResult,svgTextLines} from './plus-svg.mjs';
import {seeded} from './puzzle-core.mjs';
export function setupLifePlus(tool,mount,out){if(tool.id==='habit-tracker')return habits(mount,out);if(tool.id==='room-planner')return room(mount,out);if(tool.id==='seating-chart')return seating(mount,out);return pantry(mount,out);}
function habits(mount,out){let checks=new Set(),names=['Read','Move','Practice'],undo;mount.innerHTML='<h2>A little progress, one day at a time.</h2><form><div class="form-grid">'+[text('month','Month',today().slice(0,7),'month'),area('habits','Habit names · one per line',names.join('\n'))].map(field).join('')+'</div><div class="form-actions"><button type="submit" class="btn primary">Update habits</button><button type="button" class="btn secondary" data-export-habits>Export records JSON</button><button type="button" class="btn secondary" data-reset-month>Reset this month</button><button type="button" class="btn secondary" data-undo-month hidden>Undo reset</button></div><div class="form-error"></div></form><div class="habit-picker"></div><div class="habit-calendar"></div><p class="form-note" data-habit-status role="status">Choose a habit, then mark the dates you completed it.</p>';const f=mount.querySelector('form'),picker=mount.querySelector('.habit-picker'),calendar=mount.querySelector('.habit-calendar'),status=mount.querySelector('[data-habit-status]'),key=(name,day)=>JSON.stringify([f.elements.month.value,name,day]);let save=()=>{};
 function render(){const match=f.elements.month.value.match(/^(\d{4})-(\d{2})$/);need(match&&+match[1]>=1900&&+match[1]<=2200,'Choose a month between 1900 and 2200.');const y=+match[1],m=+match[2],days=new Date(Date.UTC(y,m,0)).getUTCDate(),start=new Date(Date.UTC(y,m-1,1)).getUTCDay(),selected=picker.querySelector('select')?.value||names[0];picker.innerHTML='<label class="field"><span>Habit to mark</span><select aria-label="Habit to mark">'+names.map(name=>'<option '+(name===selected?'selected':'')+'>'+e(name)+'</option>').join('')+'</select></label>';const name=picker.querySelector('select').value;picker.querySelector('select').onchange=render;calendar.innerHTML='<div class="habit-week">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>'<strong>'+d+'</strong>').join('')+'</div><div class="habit-days">'+Array.from({length:start},()=>'<span></span>').join('')+Array.from({length:days},(_,i)=>'<button type="button" data-day="'+(i+1)+'" aria-label="'+e(name)+', '+f.elements.month.value+'-'+String(i+1).padStart(2,'0')+'" aria-pressed="'+checks.has(key(name,i+1))+'" class="'+(checks.has(key(name,i+1))?'completed':'')+'">'+(i+1)+'</button>').join('')+'</div>';let completed=0,longest=0,run=0;for(let d=1;d<=days;d++){if(checks.has(key(name,d))){completed++;run++;longest=Math.max(longest,run);}else run=0;}const thisMonth=today().slice(0,7)===f.elements.month.value;let anchor=thisMonth?+today().slice(-2):days;if(thisMonth&&!checks.has(key(name,anchor)))anchor--;let ending=0;for(let d=anchor;d>0&&checks.has(key(name,d));d--)ending++;status.textContent=name+': '+completed+' marked days; longest run '+longest+' days; run ending '+(thisMonth?'today/yesterday':'at month end')+': '+ending+'.';
  const W=1123,H=794,left=180,cell=(W-left-42)/days,rh=Math.min(49,490/names.length);let body='<text x="42" y="153" font-size="14" font-weight="700">Habit</text>';for(let d=1;d<=days;d++)body+=`<text x="${left+(d-.5)*cell}" y="153" text-anchor="middle" font-size="12">${d}</text>`;names.forEach((habit,r)=>{const top=173+r*rh;body+=`<text x="42" y="${top+rh*.65}" font-size="12" textLength="${Math.min(130,habit.length*6)}" lengthAdjust="spacingAndGlyphs">${e(habit)}</text>`;for(let d=1;d<=days;d++){body+=`<rect x="${left+(d-1)*cell}" y="${top}" width="${cell}" height="${rh}" fill="${checks.has(key(habit,d))?'#dbe8d9':'white'}" stroke="#a5b6a9"/>`;if(checks.has(key(habit,d)))body+=`<text x="${left+(d-.5)*cell}" y="${top+rh*.65}" text-anchor="middle" font-size="15">✓</text>`;}});pagesResult(out,[pageSVG('My habit calendar',f.elements.month.value+' · self-reported completion marks',body,{width:W,height:H})],'nepocore-habit-calendar',{width:W,height:H,paper:{widthMM:297,heightMM:210},details:[['Current habit',name],['Marked days',completed],['Longest run',longest+' days']],note:'Local saving is optional. These are recorded marks, not a health assessment or a permanent backup.'});save();}
 f.onsubmit=ev=>{ev.preventDefault();try{const parsed=[...new Set(f.elements.habits.value.split('\n').map(s=>s.trim()).filter(Boolean))];need(parsed.length>0&&parsed.length<=10&&parsed.every(s=>s.length<=40),'Use 1–10 habit names, each up to 40 characters.');names=parsed;f.querySelector('.form-error').innerHTML='';render();}catch(ex){error(f.querySelector('.form-error'),ex.message);}};calendar.onclick=ev=>{const b=ev.target.closest('[data-day]');if(!b)return;const name=picker.querySelector('select').value,k=key(name,+b.dataset.day);checks.has(k)?checks.delete(k):checks.add(k);render();};mount.querySelector('[data-export-habits]').onclick=()=>download(new Blob([JSON.stringify({habits:names,checks:[...checks]},null,2)],{type:'application/json'}),'nepocore-habits.json');mount.querySelector('[data-reset-month]').onclick=()=>{undo=new Set(checks);for(const k of checks)try{if(JSON.parse(k)[0]===f.elements.month.value)checks.delete(k);}catch{}mount.querySelector('[data-undo-month]').hidden=false;render();};mount.querySelector('[data-undo-month]').onclick=()=>{if(undo)checks=undo;undo=null;mount.querySelector('[data-undo-month]').hidden=true;render();};save=localChoice(mount,'nepocore-habits-v1',payload=>{if(Array.isArray(payload?.habits)&&payload.habits.length>=1&&payload.habits.length<=10&&payload.habits.every(n=>typeof n==='string'&&n.length<=40)&&Array.isArray(payload.checks)&&payload.checks.length<=40000){names=payload.habits;checks=new Set(payload.checks.filter(k=>typeof k==='string'));f.elements.habits.value=names.join('\n');}},()=>({habits:names,checks:[...checks]}));render();return()=>save();}
export function roomItems(data,width,depth){return data.map(row=>{const rotation=+row.rotation||0,w=rotation===90?+row.depth:+row.width,h=rotation===90?+row.width:+row.depth,x=+row.x,y=+row.y;need(row.name&&row.name.length<=24&&[w,h,x,y].every(Number.isFinite)&&w>0&&h>0&&x>=0&&y>=0&&x+w<=width+.00001&&y+h<=depth+.00001,'Use furniture labels up to 24 characters and keep every rectangle inside the room with positive dimensions.');return {...row,x,y,w,h};});}
function room(mount,out){return recordForm(mount,{columns:[{id:'name',label:'Furniture'},{id:'x',label:'Left (m)',type:'number',min:0,max:30},{id:'y',label:'Top (m)',type:'number',min:0,max:30},{id:'width',label:'Width (m)',type:'number',min:.05,max:30},{id:'depth',label:'Depth (m)',type:'number',min:.05,max:30},{id:'rotation',label:'Rotation',options:[[0,'0°'],[90,'90°']],value:0}],initial:[{name:'Bed',x:.2,y:.2,width:1.4,depth:2,rotation:0},{name:'Desk',x:2.1,y:.2,width:1.2,depth:.6,rotation:0},{name:'Wardrobe',x:3.3,y:1.6,width:.5,depth:1.1,rotation:0}],fields:[num('width','Room width (m)',4,1,30,.1),num('depth','Room depth (m)',3,1,30,.1)],saveKey:'nepocore-room-v1',label:'Draw floor plan',note:'Edit measurements or drag furniture in the result. Diagram only; verify all dimensions and real clearance before buying or moving furniture.',run:(data,v,api)=>{const width=+v.width,depth=+v.depth,list=roomItems(data,width,depth),scale=Math.min(900/width,510/depth),left=58,top=132,W=1123,H=794,overlaps=[];for(let i=0;i<list.length;i++)for(let j=i+1;j<list.length;j++){const a=list[i],b=list[j];if(a.x<b.x+b.w&&b.x<a.x+a.w&&a.y<b.y+b.h&&b.y<a.y+a.h)overlaps.push(a.name+' / '+b.name);}let body=`<rect x="${left}" y="${top}" width="${width*scale}" height="${depth*scale}" fill="#f4f6f0" stroke="#294334" stroke-width="3"/>`;for(let x=.5;x<width;x+=.5)body+=`<path d="M${left+x*scale} ${top}v${depth*scale}" stroke="#dae3d7"/>`;for(let y=.5;y<depth;y+=.5)body+=`<path d="M${left} ${top+y*scale}h${width*scale}" stroke="#dae3d7"/>`;list.forEach((item,i)=>{const x=left+item.x*scale,y=top+item.y*scale;body+=`<g data-room-group="${i}"><rect data-room-item="${i}" x="${x}" y="${y}" width="${item.w*scale}" height="${item.h*scale}" rx="4" fill="${['#d9e5d2','#e9ddc8','#d9ddec','#e9d8da'][i%4]}" stroke="#53765c" stroke-width="2"/><text data-room-name="${i}" x="${x+7}" y="${y+22}" font-size="13" pointer-events="none">${e(item.name.slice(0,24))}</text></g>`;});body+=`<text x="58" y="705" font-size="14">Room: ${width} × ${depth} m · grid spacing 0.5 m · ${width*depth} m²</text>`;pagesResult(out,[pageSVG('A little room plan','Rectangular footprints · drag to move, then check clearances.',body,{width:W,height:H})],'nepocore-room-plan',{width:W,height:H,paper:{widthMM:297,heightMM:210},details:[['Footprint overlaps',overlaps.length]],note:overlaps.length?'Overlaps to review: '+overlaps.join('; '):'No rectangle overlaps were found. Door swings, walkways, services and structural requirements are not modeled.'});const svg=out.querySelector('.vector-preview svg');let drag;function point(ev){return new DOMPoint(ev.clientX,ev.clientY).matrixTransform(svg.getScreenCTM().inverse());}svg.onpointerdown=ev=>{const rect=ev.target.closest('[data-room-item]');if(!rect)return;const i=+rect.dataset.roomItem;drag={i,start:point(ev),x:list[i].x,y:list[i].y};svg.setPointerCapture(ev.pointerId);ev.preventDefault();};svg.onpointermove=ev=>{if(!drag)return;const p=point(ev),item=list[drag.i],x=Math.min(width-item.w,Math.round(Math.max(0,Math.min(width-item.w,drag.x+(p.x-drag.start.x)/scale))*100)/100),y=Math.min(depth-item.h,Math.round(Math.max(0,Math.min(depth-item.h,drag.y+(p.y-drag.start.y)/scale))*100)/100);data[drag.i].x=x;data[drag.i].y=y;const rect=svg.querySelector('[data-room-item="'+drag.i+'"]'),label=svg.querySelector('[data-room-name="'+drag.i+'"]');rect.setAttribute('x',left+x*scale);rect.setAttribute('y',top+y*scale);label.setAttribute('x',left+x*scale+7);label.setAttribute('y',top+y*scale+22);};svg.onpointerup=svg.onpointercancel=()=>{if(!drag)return;drag=null;api?.updateRows(data);api?.submit();};}});}
function seating(mount,out){return recordForm(mount,{columns:[{id:'guest',label:'Guest label'},{id:'table',label:'Table',required:false}],initial:Array.from({length:12},(_,i)=>({guest:'Guest '+(i+1),table:'Table '+(Math.floor(i/4)+1)})),fields:[area('tables','Table name | capacity','Table 1 | 4\nTable 2 | 4\nTable 3 | 4'),sel('mode','Assignment mode',[['manual','Use entered assignments'],['fill','Fill blank assignments'],['shuffle','Shuffle all assignments']],'manual'),text('seed','Shuffle set','a-little-event')],saveKey:'nepocore-seating-v1',label:'Create seating plan',note:'Use unique guest labels. Assign manually, fill blank rows or shuffle within capacities. No invitations or messages are sent.',run:(data,v)=>{const specs=v.tables.trim().split('\n').filter(Boolean).map(line=>{const [name,count]=line.split('|').map(x=>x.trim());need(name&&Number.isInteger(+count)&&+count>0&&+count<=50,'Use table name | whole capacity from 1–50.');return {name,capacity:+count,guests:[]};});need(data.every(r=>r.guest.length<=28),'Keep guest labels to 28 characters for the printed cards.');need(specs.every(t=>t.name.length<=20),'Keep table names to 20 characters.');need(specs.length>0&&specs.length<=30&&new Set(specs.map(t=>t.name)).size===specs.length,'Use up to 30 uniquely named tables.');need(new Set(data.map(r=>r.guest.trim())).size===data.length,'Use unique guest labels to avoid duplicate assignments.');const rng=seeded(v.seed),guests=[...data];if(v.mode==='shuffle'){for(let i=guests.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[guests[i],guests[j]]=[guests[j],guests[i]];}}else if(v.mode==='fill')guests.sort((a,b)=>Number(!a.table.trim())-Number(!b.table.trim()));for(const row of guests){let target;if(v.mode==='shuffle'||v.mode==='fill'&&!row.table.trim())target=specs.find(t=>t.guests.length<t.capacity);else target=specs.find(t=>t.name===row.table.trim());need(target,'A guest has no matching table, or there are not enough seats.');need(target.guests.length<target.capacity,target.name+' exceeds its capacity.');target.guests.push(row.guest);}
 const chunks=specs.flatMap(t=>Array.from({length:Math.max(1,Math.ceil(t.guests.length/18))},(_,i)=>({...t,part:i,guests:t.guests.slice(i*18,(i+1)*18)}))),pages=[];for(let start=0;start<chunks.length;start+=6){let body='';chunks.slice(start,start+6).forEach((t,i)=>{const x=40+i%3*240,y=135+Math.floor(i/3)*436;body+=`<rect x="${x}" y="${y}" width="227" height="418" rx="9" fill="#f4f7f0" stroke="#a8bcac"/><text x="${x+13}" y="${y+30}" font-size="17" font-weight="700">${e(t.name.slice(0,20))}${t.part?' · continued':''}</text><text x="${x+13}" y="${y+53}" font-size="11">Capacity ${t.capacity}</text>`;t.guests.forEach((guest,j)=>body+=`<text x="${x+13}" y="${y+81+j*17}" font-size="12">${e(guest.slice(0,29))}</text>`);});pages.push(pageSVG('A little seating plan','Manual assignments · review venue access and real seating before use.',body));}pagesResult(out,pages,'nepocore-seating-plan',{details:[['Guests',data.length],['Tables',specs.length]],note:'Names stay in this browser unless you save or export them. Relationship preferences and venue requirements are not automatically assessed.'});exportCSV(out,specs.flatMap(t=>t.guests.map(guest=>({guest,table:t.name}))),'nepocore-seating.csv');}});}
function pantry(mount,out){return recordForm(mount,{columns:[{id:'name',label:'Item'},{id:'quantity',label:'Quantity',type:'number',min:0,max:1000000},{id:'unit',label:'Unit'},{id:'location',label:'Storage location'},{id:'date',label:'Package label date',type:'date',required:false}],initial:[{name:'Rice',quantity:2,unit:'kg',location:'Cupboard',date:''},{name:'Beans',quantity:3,unit:'cans',location:'Shelf',date:''}],saveKey:'nepocore-pantry-v1',label:'Review pantry list',note:'Copy the date from the package. A calendar comparison cannot determine whether food is safe or suitable to eat.',run:data=>{const day=dateUTC(today()),list=data.map(r=>{need(Number.isFinite(+r.quantity)&&+r.quantity>=0,'Use nonnegative quantities.');let distance=null;if(r.date)distance=Math.round((dateUTC(r.date)-day)/86400000);return {...r,quantity:+r.quantity,distance};}).sort((a,b)=>(a.distance??Infinity)-(b.distance??Infinity));result(out,{label:'Recorded pantry items',value:list.length,html:table(['Item','Quantity','Location','Entered label date','Calendar comparison'],list.map(r=>[r.name,r.quantity+' '+r.unit,r.location,r.date||'Not entered',r.distance===null?'No date':r.distance<0?Math.abs(r.distance)+' days after entered date':r.distance===0?'Entered date is today':r.distance+' days before entered date'])),note:'Dates are copied records, not a safety or freshness verdict. Follow the package instructions and relevant storage guidance.'});exportCSV(out,list.map(({distance,...r})=>r),'nepocore-pantry.csv');}});}
